A self-contained calculator with basic arithmetic, decimal input, keyboard support, and responsive styling.

<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Simple Calculator</title>
  <style>
    * { box-sizing: border-box; }
    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 1rem;
      background: #f1f5f9;
      color: #172033;
      font: 16px/1.4 system-ui, sans-serif;
    }
    .calculator {
      width: min(100%, 340px);
      padding: 1rem;
      border-radius: 1rem;
      background: #fff;
      box-shadow: 0 12px 32px #1720331a;
    }
    .display {
      min-height: 4.5rem;
      display: flex;
      align-items: center;
      justify-content: flex-end;
      overflow: hidden;
      padding: .75rem;
      margin-bottom: .75rem;
      border-radius: .65rem;
      background: #eaf0f8;
      font-size: clamp(1.8rem, 9vw, 2.5rem);
      font-variant-numeric: tabular-nums;
      white-space: nowrap;
    }
    .keys { display: grid; grid-template-columns: repeat(4, 1fr); gap: .55rem; }
    button {
      min-height: 3.5rem;
      border: 0;
      border-radius: .65rem;
      background: #f1f5f9;
      color: inherit;
      font: inherit;
      font-size: 1.2rem;
      cursor: pointer;
    }
    button:hover { background: #e2e8f0; }
    button:focus-visible { outline: 3px solid #2563eb; outline-offset: 2px; }
    .operator { background: #dbeafe; color: #1d4ed8; }
    .utility { background: #e2e8f0; }
    .equals { grid-row: span 2; background: #2563eb; color: white; }
    .equals:hover { background: #1d4ed8; }
    .zero { grid-column: span 2; }
  </style>
</head>
<body>
  <main class="calculator" aria-label="Calculator">
    <output class="display" id="display" aria-live="polite" aria-label="Display">0</output>
    <div class="keys">
      <button class="utility" data-action="clear" aria-label="Clear">AC</button>
      <button class="utility" data-action="sign" aria-label="Change sign">±</button>
      <button class="utility" data-action="percent" aria-label="Percent">%</button>
      <button class="operator" data-operator="÷" aria-label="Divide">÷</button>

      <button data-digit="7">7</button><button data-digit="8">8</button><button data-digit="9">9</button>
      <button class="operator" data-operator="×" aria-label="Multiply">×</button>

      <button data-digit="4">4</button><button data-digit="5">5</button><button data-digit="6">6</button>
      <button class="operator" data-operator="−" aria-label="Subtract">−</button>

      <button data-digit="1">1</button><button data-digit="2">2</button><button data-digit="3">3</button>
      <button class="operator" data-operator="+" aria-label="Add">+</button>

      <button class="zero" data-digit="0">0</button><button data-action="decimal">.</button>
      <button class="equals" data-action="equals" aria-label="Equals">=</button>
    </div>
  </main>
  <script>
    const display = document.querySelector('#display');
    let current = '0';
    let stored = null;
    let operator = null;
    let startNew = false;

    function render() { display.textContent = current; }
    function inputDigit(digit) {
      if (current === 'Error' || startNew) { current = digit; startNew = false; }
      else if (current === '0') current = digit;
      else if (current.length < 14) current += digit;
      render();
    }
    function calculate() {
      if (operator === null || stored === null) return;
      const a = stored, b = Number(current);
      let result;
      if (operator === '+') result = a + b;
      if (operator === '−') result = a - b;
      if (operator === '×') result = a * b;
      if (operator === '÷') result = b === 0 ? NaN : a / b;
      current = Number.isFinite(result)
        ? String(Number(result.toPrecision(12)))
        : 'Error';
      stored = null;
      operator = null;
      startNew = true;
      render();
    }
    function chooseOperator(nextOperator) {
      if (current === 'Error') return;
      if (operator && !startNew) calculate();
      stored = Number(current);
      operator = nextOperator;
      startNew = true;
    }
    function perform(action) {
      if (action === 'clear') {
        current = '0'; stored = null; operator = null; startNew = false;
      } else if (action === 'decimal') {
        if (current === 'Error' || startNew) { current = '0.'; startNew = false; }
        else if (!current.includes('.')) current += '.';
      } else if (action === 'sign' && current !== 'Error' && Number(current) !== 0) {
        current = String(-Number(current));
      } else if (action === 'percent' && current !== 'Error') {
        current = String(Number(current) / 100);
      } else if (action === 'equals') calculate();
      render();
    }

    document.querySelector('.keys').addEventListener('click', (event) => {
      const button = event.target.closest('button');
      if (!button) return;
      if (button.dataset.digit !== undefined) inputDigit(button.dataset.digit);
      if (button.dataset.operator) chooseOperator(button.dataset.operator);
      if (button.dataset.action) perform(button.dataset.action);
    });

    document.addEventListener('keydown', (event) => {
      if (/^[0-9]$/.test(event.key)) inputDigit(event.key);
      else if (event.key === '.') perform('decimal');
      else if (event.key === 'Enter' || event.key === '=') perform('equals');
      else if (event.key === 'Escape' || event.key === 'Delete') perform('clear');
      else if (event.key === 'Backspace') {
        current = current.length > 1 ? current.slice(0, -1) : '0';
        render();
      } else if (event.key === '+') chooseOperator('+');
      else if (event.key === '-') chooseOperator('−');
      else if (event.key === '*') chooseOperator('×');
      else if (event.key === '/') { event.preventDefault(); chooseOperator('÷'); }
      else return;
      event.preventDefault();
    });
  </script>
</body>
</html>

